    },
    "scope": {
      "type": "string",
      "enum": [
        "project",
        "user"
      ],
      "description": "Where to store: project (default) or user (global)."
    }
  },
  "required": [
    "text"
  ]
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
